// Normalize incoming lead to standard schema
const input = $input.first().json;

const lead = {
  source: input.source || 'unknown',
  source_detail: input.source_detail || '',
  first_name: input.first_name || '',
  last_name: input.last_name || '',
  email: input.email || '',
  company: input.company || '',
  job_title: input.job_title || '',
  phone: input.phone || '',
  message: input.message || '',
  submitted_at: input.submitted_at || new Date().toISOString(),
  received_at: new Date().toISOString()
};

return [{ json: lead }];

// Lead scoring based on information quality
// Scoring criteria from Dirk:
//   - gmail/free email only, no other info = Very Low
//   - company email domain = +High
//   - company name provided = +Medium
//   - additional comment/message = +Medium
//   - SAP Store source = +Medium (higher value channel)

const lead = $input.first().json;
let score = 0;
const signals = [];

// Email domain check
const email = lead.email.toLowerCase();
const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'aol.com', 'icloud.com', 'mail.com', 'protonmail.com'];
const domain = email.split('@')[1] || '';
const isFreeEmail = freeProviders.some(p => domain === p);

if (!isFreeEmail && domain) {
  score += 30;
  signals.push('company_email');
} else {
  signals.push('free_email');
}

// Company name
if (lead.company && lead.company.trim().length > 1) {
  score += 20;
  signals.push('has_company');
}

// Message content
if (lead.message && lead.message.trim().length > 20) {
  score += 20;
  signals.push('has_message');
}

// Job title
if (lead.job_title && lead.job_title.trim().length > 1) {
  score += 10;
  signals.push('has_job_title');
}

// Phone
if (lead.phone && lead.phone.trim().length > 5) {
  score += 5;
  signals.push('has_phone');
}

// SAP Store bonus
if (lead.source_detail === 'sap-store') {
  score += 15;
  signals.push('sap_store_source');
}

// Determine tier
let tier = 'low';
if (score >= 50) tier = 'high';
else if (score >= 25) tier = 'medium';

return [{
  json: {
    ...lead,
    scoring: {
      score,
      tier,
      signals,
      scored_at: new Date().toISOString()
    }
  }
}];
